import {
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react-native";

import type { Session } from "./session";
import { InvalidEmailError } from "./session";
import { SignInScreen } from "./sign-in-screen";

const mockSignIn = jest.fn();
const mockTrackScreenView = jest.fn();
const mockUseLocalSearchParams = jest.fn();

let mockSession: Session | null = null;

jest.mock("./session-context", () => ({
  useSession: () => ({
    session: mockSession,
    status: "ready",
    signIn: mockSignIn,
    signOut: jest.fn(),
  }),
}));

// eslint-disable-next-line @typescript-eslint/no-require-imports -- jest.mock's
// factory cannot reference an out-of-scope import, so `Text` is required
// lazily here instead.
jest.mock("expo-router", () => ({
  useLocalSearchParams: () => mockUseLocalSearchParams(),
  Redirect: ({ href }: { href: string }) => {
    const { Text } = require("react-native");
    return <Text testID="redirect">{href}</Text>;
  },
}));

jest.mock("@/analytics/analytics", () => ({
  trackScreenView: (...args: unknown[]) => mockTrackScreenView(...args),
}));

